        if isinstance(expression, (list, tuple)):
            return [absorb_expression(exp) for exp in expression]
        elif isinstance(expression, (bool, int, float)):
            return expression
        elif expression is None:
            return None
        else:
            raise ValueError("Invalid expression type")

    def _absorb_and_negative(args):
        if args[0] == '(&' and args[1] == ')' and args[2] == '|':
            return absorb_expression(args[3])
        elif args[0] == '|' and args[1] == '(' and args[2] == '&':
            return absorb_expression(args[3])
        elif args[0] == '(' and args[1] == '&' and args[2] == ')' and args[3] == '|':
            return absorb_expression(args[4])
        elif args[0] == '(' and args[1] == '|' and args[2] == '&':
            return absorb_expression(args[3])
        else:
            raise ValueError("Invalid argument format")

    _absorb_expression(args)
    _absorb_and_negative(args)

