    import borgmatic.core
    import click

    @click.command()
    @click.argument('completion_script', type=click.File('w+'), required=False)
    @click.option('-n', '--namespace', type=str, help='The namespace to complete')
    @click.option('-c', '--command', type=str, help='The command to complete')
    def completion(completion_script, namespace, command):
        if namespace is None or command is None:
            return
        try:
            ctx = borgmatic.core.Context(completion_script, namespace)
            command = ctx.command.get_command(ctx, command)
            if command:
