def parse_subparser_arguments(unparsed_arguments, subparsers):
    parsed_args = {}
    remaining_args = []
    for subparser_name, subparser in subparsers.items():
        try:
            parsed_args_for_subparser, remaining_args = subparser.parse_known_args(unparsed_arguments)
            parsed_args[subparser_name] = parsed_args_for_subparser
            for arg in remaining_args:
