    return parsed_args, remaining_args

def paging(response, max_results):
    if not isinstance(response, list):
        raise ValueError("response must be a list")
    if not isinstance(max_results, int) or max_results <= 0:
        raise ValueError("max_results must be a positive integer")

    result_gen = iter(response)
    while True:
        page = []
        for _ in range(min(max_results, len(result_gen))):
            page.append(next(result_gen))
        if not page:
            return
        yield page

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """

    if not size or not isinstance(size, str):
        raise ValueError("Invalid input size")

    size = size.strip()
    if size.isdigit():
        return int(size)

    units = ("", "K", "M", "G", "T", "P", "E", "Z", "Y")
    for i, unit in enumerate(units):
        if size.endswith(unit):
            return int(size[:-len(unit)]) * (1000 ** i)

    raise ValueError("Invalid size unit")

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    # Parse the input string to extract the numerical value and unit
    # If no unit is specified, assume bytes
    if size[-1].isalpha():
        unit = size[-1].upper()
    else:
        unit = "B"

    try:
        value = float(size[:-1])
    except ValueError:
        raise ValueError("Invalid file size: {}".format(size))

    if unit == "B":
        return int(value)
    elif unit in ["K", "KB"]:
        return int(value * 1024)
    elif unit in ["M", "MB"]:
        return int(value * 1024**2)
    elif unit in ["G", "GB"]:
        return int(value * 1024**3)
    elif unit in ["T", "TB"]:
        return int(value * 1024**4)
    elif unit in ["P", "PB"]:
        return int(value * 1024**5)
    elif unit in ["E", "EB"]:
        return int(value * 1024**6)
    elif unit in ["Z", "ZB"]:
        return int(value * 1024**7)
    elif unit in ["Y", "YB"]:
        return int(value * 1024**8)
    else:
        raise ValueError("Invalid unit: {}".format(unit))

    return int(value * 1024**float(unit))

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    size = size.upper()
    size_dict = {"K": 1000, "KB": 1000, "MB": 1000**2, "GB": 1000**3, "TB": 1000**4, "PB": 1000**5, "EB": 1000**6, "ZB": 1000**7}
    for unit in size_dict:
        if unit in size:
            return int(float(size.replace(unit, "")) * size_dict[unit])
    return int(size)

