def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    if not string:
        raise ValueError("string cannot be empty")
    if not alphabet:
        raise ValueError("alphabet cannot be empty")
    if len(string) > len(alphabet):
        raise ValueError("length of string cannot be greater than length of alphabet")
    inverse_alphabet = dict(zip(alphabet, xrange(0, len(alphabet))))
    n = 0
    exp = 0
    for i in reversed(string):
        if i not in inverse_alphabet:
            raise ValueError(f"character {i} not found in alphabet")
        n += inverse_alphabet[i] * (len(alphabet) ** exp)
        exp += 1
    return n

