def prepare_repository_from_archive(archive_path, filename=None, tmp_path="/tmp"):
    if not os.path.exists(archive_path):
        raise FileNotFoundError(f"Archive {archive_path} does not exist")

    if filename is None:
        filename = os.path.basename(archive_path)

    tmp_dir = os.path.join(tmp_path, os.path.splitext(filename)[0])
    if not os.path.exists(tmp_dir):
        os.makedirs(tmp_dir)

    subprocess.run(["tar", "-xvf", archive_path, "-C", tmp_dir])

    repo_url = os.path.join(tmp_dir, "repository")
    if not os.path.exists(repo_url):
        raise ValueError(f"Repository not found in archive {archive_path}")

    return repo_url

