    for char in frequency:
        if char.isdigit():
            number += char
        else:
            unit += char

    if not number or not unit:
        raise ValueError("Frequency string is invalid.")

    number = int(number)
    if unit.lower() == "week":
        return datetime.timedelta(weeks=number)
    elif unit.lower() == "day":
        return datetime.timedelta(days=number)
    elif unit.lower() == "hour":
        return datetime.timedelta(hours=number)
    elif unit.lower() == "minute":
        return datetime.timedelta(minutes=number)
    elif unit.lower() == "second":
        return datetime.timedelta(seconds=number)
    else:
