def process_text_links(text):
    def linkify_text(string):
        if string.startswith('http://') or string.startswith('https://'):
            return '<a href="{}">{}</a>'.format(string, string)
        else:
            return string
    def add_attributes(string):
        return 'target="_blank"' if string.startswith('http://') or string.startswith('https://') else None
    text_parts = text.split(' ')
    for i in range(len(text_parts)):
        if text_parts[i].startswith('http://') or text_parts[i].startswith('https://'):
            text_parts[i] = linkify_text(text_parts[i])
            if add_attributes(text_parts[i]) is not None:
                text_parts[i] += ' ' + add_attributes(text_parts[i])
    return ' '.join(text_parts)

