def fetch_content_type(url: str) -> Optional[str]:
    """
    Fetch the HEAD of the remote url to determine the content type.
    """
    if not url:
        return None

    try:
        with urlopen(url, timeout=5) as response:
            content_type = response.info().get("Content-Type")
            if content_type:
                return content_type.split(";")[0].strip()
    except OSError:
        return None

    return None

def fetch_content_type(url: str) -> Optional[str]:
    """
    Fetch the HEAD of the remote url to determine the content type.
    """
    try:
        resp = urlopen(Request(url, method="HEAD"))
        content_type = resp.info().get("Content-Type")
        if content_type is not None:
            return content_type.split(";")[0].strip()
    except Exception:
        pass
    return None

def fetch_content_type(url: str) -> Optional[str]:
    """
    Fetch the HEAD of the remote url to determine the content type.
    """
    try:
        request = Request(
            url, headers={'User-Agent': 'Mozilla/5.0'}, method='HEAD'
        )
        with urlopen(request) as response:
            return response.info().get('Content-Type', '')
    except HTTPError as e:
        if e.code == 405 and e.msg == 'Method Not Allowed':
            return None
        raise
    except URLError as e:
        if isinstance(e.reason, socket.timeout):
            return None
        raise
    except Exception:
        return None

