def get_nodeinfo_well_known_document(url, document_path=None):
    """
    Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    # Check if the URL is valid
    try:
        parsed_url = urlparse(url)
        assert parsed_url.scheme and parsed_url.netloc
    except (ValueError, AssertionError):
        raise ValueError("Invalid URL: %s" % url)

    # Build the document path
    if not document_path:
        document_path = "/.well-known/nodeinfo"
    document_url = urljoin(url, document_path)

    # Fetch the document
    try:
        response = requests.get(document_url)
        response.raise_for_status()
        document = response.json()
    except requests.exceptions.RequestException as req_error:
        raise NodeInfoDocumentError("Failed to fetch NodeInfo document: %s" % req_error)
    except (ValueError, json.JSONDecodeError) as json_error:
        raise NodeInfoDocumentError("Failed to parse NodeInfo document: %s" % json_error)

    # Validate the document
    if not isinstance(document, dict):
        raise NodeInfoDocumentError("NodeInfo document must be a JSON object")
    if "version" not in document:
        raise NodeInfoDocumentError("NodeInfo document must have a 'version' field")
    if document["version"] != "1.0":
        raise NodeInfoDocumentError("Unsupported NodeInfo version: %s" % document["version"])
    if "nodes" not in document:
        raise NodeInfoDocumentError("NodeInfo document must have a 'nodes' field")
    nodes = document["nodes"]
    if not isinstance(nodes, list):
        raise NodeInfoDocumentError("'nodes' field must be a list")
    if not nodes:
        raise

