def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    if not isinstance(public_key, rsa.PublicKey):
        raise TypeError("public_key must be an rsa.PublicKey instance")

    if not isinstance(doc, etree._Element):
        raise TypeError("doc must be an etree._Element instance")

    if not isinstance(signature, etree._Element):
        raise TypeError("signature must be an etree._Element instance")

    # Extract the signature value
    signature_value = signature.text

    # Extract the signed info
    signed_info = signature.getparent()

    # Convert the signed info to a byte string
    signed_info_str = etree.tostring(signed_info, encoding="utf-8")

    # Verify the signature
    try:
        return public_key.verify(signature_value.encode("utf-8"), signed_info_str)
    except rsa.pkcs1.PSSSignerException:
        return False
