def parse_diaspora_webfinger(document: str) -> Dict:
    try:
        data = json.loads(document)
        try:
            link = next(link for link in data['links'] if link['rel'] == 'hcard_url')
        except StopIteration:
            return None
        return {'hcard_url': link['href']}
    except json.decoder.JSONDecodeError:
        tree = ElementTree.fromstring(document)
        links = tree.findall(".//{http://docs.oasis-open.org/ns/xri/xrd-1.0}Link[@rel='hcard_url']")
        if not links:
            return None
        return {'hcard_url': links[0].text}

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        if document.startswith("<"):
            # XRD format
            root = ET.fromstring(document)
            self_tags = root.findall(".//{http://docs.oasis-open.org/ns/xri/xrd-1.0}XRD/{http://docs.oasis-open.org/ns/xri/xrd-1.0}Self")
            if len(self_tags) != 1:
                return None
            self_tag = self_tags[0]
            id_tag = self_tag.find("{{http://docs.oasis-open.org/ns/xri/xrd-1.0}}Identifier")
            if not id_tag:
                return None
            url = id_tag.text.strip()
            return { "url": url }
        else:
            # JSON format
            data = json.loads(document)
            if "links" not in data:
                return None
            links = data["links"]
            for link in links:
                if "rel" not in link:
                    continue
                if link["rel"] != "http://schemas.microsoft.com/ado/2007/08/dataservices/related/hcard":
                    continue
                if "title" not in link:
                    continue
                if link["title"] != "HCard":
                    continue
                if "href" not in link:
                    continue
                hcard_url = link["href"]
                return { "hcard_url": hcard_url }
            return None
    except (ValueError, KeyError) as e:
        return None

def parse_diaspora_webfinger(document: str) -> Dict:
    if document is None or document.strip() == "":
        return {}
    try:
        doc_json = json.loads(document)
        if isinstance(doc_json, dict) and "links" in doc_json:
            # JSON format
            link = doc_json["links"][0]
            return {
                "subject": link["subject"],
                "links": link["links"],
            }
        elif isinstance(doc_json, list):
            # XRD format
            xrd = XRD.from_dict(doc_json)
            return {
                "subject": xrd.subject,
                "links": [link.to_dict() for link in xrd.links]
            }
        else:
            # invalid format
            return {}
    except (ValueError, KeyError):
        return {}
    except:
        return {}

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if not document:
        return None

    try:
        json_doc = json.loads(document)
        if "links" in json_doc and len(json_doc["links"]) > 0:
            return json_doc
    except (json.JSONDecodeError, KeyError):
        pass

    try:
        xml_doc = ElementTree.fromstring(document)
        xrd_node = xml_doc.find("/XRD")
        if xrd_node is not None:
            links_node = xrd_node.find("links")
            if links_node is not None:
                links = []
                for link_node in links_node:
                    links.append({
                        "rel": link_node.attrib["rel"],
                        "type": link_node.attrib["type"],
                        "href": link_node.attrib["href"],
                    })
                return {
                    "links": links,
                }
    except (ElementTree.ParseError, KeyError):
        pass

    return None

