def validate_from_content(spec_content=None):
    """validates that spec (YAML) content has all required fields

    :param spec_content: content of spec file
    :raise IRValidatorException: when mandatory data
    is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    if not spec_content:
        raise IRValidatorException("spec_content cannot be empty")
    try:
        data = yaml.safe_load(spec_content)
    except yaml.YAMLException as e:
        raise IRValidatorException(f"Spec content is not valid YAML: {e}")
    if not isinstance(data, dict):
        raise IRValidatorException("Spec content must be a YAML mapping")
    if "info" not in data:
        raise IRValidatorException("Info field is missing from spec")
    if "title" not in data["info"]:
        raise IRValidatorException("Title field is missing from info")
    if "title" not in data["info"]:
        raise IRValidatorException("Description field is missing from info")
    return data

def validate_from_file(cls, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    try:
        with open(yaml_file, 'r') as f:
            data = yaml.safe_load(f)

        for field in cls.MANDATORY_FIELDS:
            if field not in data:
                raise IRValidatorException(f"Mandatory field `{field}` is missing in YAML file.")

        return data
    except IOError as e:
        raise IRValidatorException(f"Error reading YAML file: {e}")
    except yaml.YAMLError as e:
        raise IRValidatorException(f"Error parsing YAML data: {e}")

