def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    spec_defaults = self._get_defaults(self.spec)
    # remove any non-default arguments from the spec defaults
    for arg, val in spec_defaults.items():
        if self.args[arg] is not self.spec.args[arg]:
            del spec_defaults[arg]
    # add any remaining defaults from the default spec
    for arg, val in self.spec.args.items():
