def get_parser_option_specs(command_name: str) -> List[CommandSpec]:
    parser = optparse.OptionParser()
    parser.add_option(
        '--all', action='store_true', default=False,
        help='include all options in the list')
    parser.add_option(
        '-u', '--user-options', action='store_true', default=False,
        help='include user-specific options in the list')

    options, _ = parser.parse_args()

    if options.all:
        return list(parser)

    curr_command = self.command_registry[command_name]
    curr_options = []
    for opt in parser:
        if opt.startswith('-'):
            curr_options.append(opt.strip('-'))
        else:
            curr_options.append(opt)

    if options.user_options:
        user_options = self.get_user_options(command_name)
        curr_options.extend(user_options)

    return curr_options

