    cls = None
    if type_name == "string":
        cls = CreateStringType(spec_option)
    elif type_name == "integer":
        cls = CreateIntegerType(spec_option)
    elif type_name == "float":
        cls = CreateFloatType(spec_option)
    elif type_name == "boolean":
        cls = CreateBooleanType(spec_option)
    elif type_name == "enum":
        cls = CreateEnumType(spec_option)
    else:
        raise ValueError(f"Unsupported type '{type_name}' for the argument '{option_name}' in the command '{subcommand}'.")

    # Return the complex type instance.
    return cls

def get_nested_custom_and_control_args(self, args):
    """
    Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
    will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
    into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
    normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}
    custom_args = {}

    for k, v in args.items():
        if k.startswith('control' or k.startswith('nested')):
            control_args[k] = v
        elif k.startswith('custom'):
            custom_args[k] = v
        else:
            nested_args[k] = v

    return control_args, nested_args, custom_args

