def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if not vars_dict:
        return {}
    if not extra_vars:
        return vars_dict
    if isinstance(extra_vars, list):
        vars_dict = {**vars_dict, **{k: v for k, v in extra_vars}}
    else:
        raise ValueError("Extra-vars must be a list or dictionary")
    return vars_dict

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if not extra_vars:
        return vars_dict
    for var, value in extra_vars.items():
        if var in vars_dict and isinstance(vars_dict[var], dict):
            vars_dict[var].update(value)
        else:
            vars_dict[var] = value
    return vars_dict

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if extra_vars is None:
        return vars_dict

    new_dict = {}
    for key, value in vars_dict.items():
        if key not in extra_vars:
            new_dict[key] = value

    for key, value in extra_vars.items():
        if key not in vars_dict:
            new_dict[key] = value
        elif isinstance(value, dict):
            new_dict[key] = merge_extra_vars(vars_dict[key], value)
        elif isinstance(value, list):
            new_dict[key] = vars_dict[key] + value
        else:
            new_dict[key] = value

    return new_dict

