def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """

    parser = None
    if parser_name == "main":
        parser = self._main_parser
    elif parser_name == "virsh":
        parser = self._virsh_parser
    elif parser_name == "ospd":
        parser = self._ospd_parser

    for arg in parser.args:
        if arg.default is None:
            continue
        if arg.default.isdigit() and arg.default not in values_dict:
            values_dict[arg.dest] = int(arg.default)
        elif arg.default.replace(".", "", 1).isdigit() and arg.default not in values_dict:
            values_dict[arg.dest] = float(arg.default)
        elif arg.default.lower() in ["true", "false"] and arg.default not in values_dict:
            values_dict[arg.dest] = arg.default.lower() == "true"

    return values_dict

